// ───────────────────────────────────────────────────────────────
// FILTRA LEADS: contatos da UAZAPI − compradores − já enviados
// Sem LLM: pura normalização + comparação por chave de telefone.
// ───────────────────────────────────────────────────────────────

// 1) Coleta os chats da resposta da UAZAPI (tolerante a vários formatos)
const rawItems = $('UAZAPI - Buscar Chats').all();
let chats = [];
for (const it of rawItems) {
  const j = it.json;
  if (Array.isArray(j)) chats.push(...j);
  else if (Array.isArray(j.chats)) chats.push(...j.chats);
  else if (Array.isArray(j.data)) chats.push(...j.data);
  else if (Array.isArray(j.results)) chats.push(...j.results);
  else if (j && typeof j === 'object') chats.push(j);
}
console.log('Total de chats brutos:', chats.length);

// 2) Helpers de normalização (resolve +55, sufixos e o 9º dígito BR)
function onlyDigits(s) { return (s == null ? '' : String(s)).replace(/\D/g, ''); }
function chave(raw) {
  let d = onlyDigits(raw);
  if (d.startsWith('55') && d.length >= 12) d = d.slice(2); // tira código do país
  if (d.length === 11) d = d.slice(0, 2) + d.slice(3);      // tira o 9 extra (DDD+9+8 → DDD+8)
  return d; // chave canônica = DDD + 8 dígitos
}

// 3) Conjunto de COMPRADORES (usuarios.telefone)
const buyers = new Set(
  $('Compradores (usuarios)').all()
    .map(i => chave(i.json.telefone))
    .filter(Boolean)
);
console.log('Compradores:', buyers.size);

// 4) Conjunto de JÁ ENVIADOS (remarketing_enviados.telefone_chave)
const sent = new Set(
  $('Já Enviados').all()
    .map(i => i.json.telefone_chave)
    .filter(Boolean)
);
console.log('Já enviados:', sent.size);

// 5) Monta os leads elegíveis
const vistos = new Set();
const out = [];
for (const chat of chats) {
  const rawId = chat.wa_chatid || chat.id || chat.chatid || chat.jid ||
                chat.number || chat.phone || chat.wa_fastid || '';
  // pula grupos, broadcast e status
  if (chat.wa_isGroup === true || /@g\.us/i.test(rawId)) continue;
  if (/@broadcast|status@/i.test(rawId)) continue;

  const numero = onlyDigits(String(rawId).split('@')[0].split(':')[0]);
  if (!numero || numero.length < 10) continue; // descarta ids estranhos

  const k = chave(numero);
  if (!k) continue;
  if (buyers.has(k)) continue;   // já comprou → fora
  if (sent.has(k)) continue;     // já recebeu → fora
  if (vistos.has(k)) continue;   // duplicado nesta rodada → fora
  vistos.add(k);

  const nome = chat.wa_name || chat.name || chat.lead_name ||
               chat.wa_contactName || chat.lead_fullName || '';

  out.push({ json: { numero, chave: k, nome } });
}

console.log('Leads elegíveis para remarketing:', out.length);
return out;
